		import urllib.parse

		query_string = request.query_string.decode('utf-8')
		paramLoc = query_string.find("Handler01217" + '=')
		if paramLoc == -1:
			return f"request.query_string did not contain expected parameter \'{"Handler01217"}\'."
		param = query_string[paramLoc + len("Handler01217") + 1:]
		ampLoc = param.find('&')
